+import assert from 'node:assert';
+import fs from 'node:fs';
+const src = fs.readFileSync('src/app/api/openai/assistant/route.ts', 'utf8');
+assert(!/beta\.(threads|assistants)/.test(src));
+assert(src.includes('responses.create'));
+process.env.OPENAI_API_KEY = 'x';
+const calls: { url: string; body: any }[] = [];
+let n = 0;
+(globalThis as any).fetch = async (url: any, init: any) => {
+  const body = init?.body ? JSON.parse(init.body) : {};
+  calls.push({ url: String(url), body });
+  const u = String(url);
+  const json = (o: any) => new Response(JSON.stringify(o), { headers: { 'content-type': 'application/json' } });
+  if (u.endsWith('/conversations')) return json({ id: 'conv_1', object: 'conversation' });
+  n++;
+  if (n === 1)
+    return json({ id: 'resp_1', object: 'response', status: 'completed', output: [
+      { type: 'function_call', id: 'fc_1', call_id: 'call_1', name: 'getRoomTemperature', arguments: '{"room":"kitchen"}', status: 'completed' }] });
+  return json({ id: 'resp_2', object: 'response', status: 'completed', output: [
+    { type: 'message', id: 'm', role: 'assistant', status: 'completed', content: [{ type: 'output_text', text: 'It is 22', annotations: [] }] }] });
+};
+const { POST } = await import('../src/app/api/openai/assistant/route.ts');
+const res = await POST(new Request('http://x/api', { method: 'POST', body: JSON.stringify({ threadId: null, message: 'kitchen temp?' }) }));
+const text = await res.text();
+assert(text.includes('conv_1'), text);
+assert(text.includes('It is 22'), text);
+const rc = calls.filter(c => c.url.endsWith('/responses'));
+assert.strictEqual(rc.length, 2);
+assert.strictEqual(rc[0].body.conversation, 'conv_1');
+assert.strictEqual(rc[0].body.tools.length, 2);
+assert.deepStrictEqual(rc[1].body.input[0], { type: 'function_call_output', call_id: 'call_1', output: '22' });
+console.log('ok');

