+// Drives the real spell-check and vision route handlers with a stubbed chat.completions.create.
+// Run: OPENAI_API_KEY=x npx tsx test/openai-model.test.mjs
+import assert from 'node:assert';
+
+import OpenAI from 'openai';
+const bodies = [];
+import { createRequire } from 'node:module';
+const CJS = createRequire(import.meta.url)('openai');
+const fake = async function (body) {
+  bodies.push({ url: '/chat/completions', body });
+  const chunk = (d, fin) => ({ id: 'c', object: 'chat.completion.chunk', created: 1, model: 'm', choices: [{ index: 0, delta: d, finish_reason: fin }] });
+  return (async function* () { yield chunk({ role: 'assistant', content: '[]' }, null); yield chunk({}, 'stop'); })();
+};
+for (const C of new Set([OpenAI, CJS.default ?? CJS, CJS])) if (C?.Chat?.Completions) C.Chat.Completions.prototype.create = fake;
+
+const spell = await import('../src/app/api/openai/spell-check/route.ts');
+const res = await spell.POST(new Request('http://x/', { method: 'POST', body: JSON.stringify({ prompt: 'helo' }) }));
+assert.strictEqual(await res.text(), '[]');
+
+const vision = await import('../src/app/api/openai/chat-with-vision/route.ts');
+await (await vision.POST(new Request('http://x/', { method: 'POST', body: JSON.stringify({ messages: [{ role: 'user', content: 'hi' }], data: { imageUrl: 'http://i/x.png' } }) }))).text();
+
+assert.strictEqual(bodies.length, 2);
+for (const { url, body } of bodies) {
+    assert.strictEqual(body.model, 'gpt-5.6-terra');
+  assert.strictEqual(body.stream, true);
+  assert(body.max_completion_tokens >= 1000);
+  for (const k of ['max_tokens', 'temperature', 'top_p', 'frequency_penalty', 'presence_penalty'])
+    assert(!(k in body), k);
+}
